// ── State ──────────────────────────────────────────
  let players      = {};   // { name: { shots, photo, stoppedAt, joinedRound } }
  let removedPlayers = {}; // players who quit — kept for receipt
  let round        = 1;
  let modalResolve = null;

  // Camera state
  let camStream    = null;
  let camState     = 'idle'; // idle | live | captured
  let capturedPhoto = null;  // base64 data URL
  let camFacingMode = 'user'; // 'user' (front) or 'environment' (back)
  let camDevices   = [];     // list of video input devices
  let drinkOrder   = [];     // sequential drink order array
  let currentDrinkerIdx = 0; // who is currently drinking

  // Timer
  let timerSecs    = 300;
  let timeLeft     = 300;
  let timerRunning = false;
  let timerIv      = null;

  // Alert phrases
  const PHRASES = [
    { big: 'INOM NA!',  sub: 'TAGAY NA!!!' },
    { big: 'INOM NA!',  sub: 'BAKIT HINDI KA NATAGAY?!' },
    { big: 'INOM NA!',  sub: 'DALAWANG BASO NA SHOT YAN!' },
    { big: 'INOM NA!',  sub: 'HUWAG MAHIYA — INOM!' },
    { big: 'TAGAY MO NA KANINA PA!', sub: 'INOM NA!!!' },
  ];
  let phraseIdx = 0;

  // ── Custom Audio Alarm ─────────────────────────────────────
  const ALARM_AUDIO_SRC = "data:audio/mpeg;base64,";
  const DISMISS_AUDIO_SRC = "data:audio/mpeg;base64,";
  const REMOVE_AUDIO_SRC = "data:audio/mpeg;base64,";
  let alarmAudio = null;
  let removeAudio = null;

  // ── AudioContext unlock for Android WebView ────────
  let _audioUnlocked = false;
  function _unlockAudio() {
    if (_audioUnlocked) return;
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const buf = ctx.createBuffer(1, 1, 22050);
      const src = ctx.createBufferSource();
      src.buffer = buf; src.connect(ctx.destination); src.start(0);
      ctx.resume().then(() => { _audioUnlocked = true; });
    } catch(e) {}
  }
  document.addEventListener('touchstart', _unlockAudio, { once: true });
  document.addEventListener('click', _unlockAudio, { once: true });

  function playAlarmAudio() {
    _unlockAudio();
    stopAlarmAudio();
    try {
      alarmAudio = new Audio(ALARM_AUDIO_SRC);
      alarmAudio.volume = 1;
      alarmAudio.loop = true;
      const p = alarmAudio.play();
      if (p !== undefined) {
        p.catch(() => setTimeout(() => alarmAudio && alarmAudio.play().catch(() => {}), 400));
      }
    } catch(e) { console.log('Alarm audio error:', e); }
  }

  function stopAlarmAudio() {
    if (alarmAudio) {
      alarmAudio.pause();
      alarmAudio.currentTime = 0;
      alarmAudio = null;
    }
  }

  function repeatAlarm() { playAlarmAudio(); }

  function playRemoveAudio() {
    _unlockAudio();
    stopRemoveAudio();
    try {
      removeAudio = new Audio(REMOVE_AUDIO_SRC);
      removeAudio.volume = 0.85;
      removeAudio.loop = false;
      removeAudio.play().catch(() => setTimeout(() => removeAudio && removeAudio.play().catch(()=>{}), 400));
    } catch(e) {}
  }

  function stopRemoveAudio() {
    if (removeAudio) {
      removeAudio.pause();
      removeAudio.currentTime = 0;
      removeAudio = null;
    }
  }

  // ── Timer ──────────────────────────────────────────
  function changeTimeout() {
    timerSecs = parseInt(document.getElementById('timeoutSel').value);
    if (!timerRunning) { timeLeft = timerSecs; renderTimer(); }
  }

  function startTimer() {
    // Always restart fresh for the current player's turn
    clearInterval(timerIv);
    timerIv = null;
    timeLeft = timerSecs;
    timerRunning = true;
    renderTimer();
    timerIv = setInterval(tick, 1000);
    const current = getCurrentDrinker();
    if (current) toast(`⏱ ${current} — Timer started!`);
    else toast('⏱ Timer started!');
  }

  function stopTimer() {
    clearInterval(timerIv);
    timerIv = null;
    timerRunning = false;
    timeLeft = timerSecs;
    stopAlarmAudio();
    renderTimer();
    toast('⏹ Timer stopped.');
  }

  // Called after a player drinks — moves turn to next player and auto-restarts timer
  function advanceTurnAndRestart(drinkerName) {
    const idx = drinkOrder.indexOf(drinkerName);
    if (idx !== -1) {
      currentDrinkerIdx = (idx + 1) % drinkOrder.length;
    }
    // Auto-start the timer for the next player
    clearInterval(timerIv);
    timerIv = null;
    timeLeft = timerSecs;
    timerRunning = true;
    timerIv = setInterval(tick, 1000);
    renderTimer();
  }

  function resetCountdown() {
    clearInterval(timerIv);
    timerIv = null;
    timeLeft = timerSecs;
    if (timerRunning) timerIv = setInterval(tick, 1000);
    renderTimer();
  }

  function tick() {
    timeLeft = Math.max(0, timeLeft - 1);
    renderTimer();
    if (timeLeft === 0) {
      clearInterval(timerIv);
      timerRunning = false;
      fireAlarm();
    }
  }

  function renderTimer() {
    const m = Math.floor(timeLeft / 60);
    const s = timeLeft % 60;
    const el = document.getElementById('timerDisplay');
    el.textContent = `${m}:${s.toString().padStart(2,'0')}`;
    el.className = 'tb-time' +
      (timeLeft <= 10 ? ' danger' : timeLeft <= 60 ? ' warn' : '');
    updateTimerBanner();
    if (document.getElementById('takeShot').classList.contains('active')) renderShotList();
  }

  // ── Alarm ──────────────────────────────────────────
  function fireAlarm() {
    const p = PHRASES[phraseIdx % PHRASES.length];
    phraseIdx++;
    document.getElementById('vaBig').textContent = p.big;
    document.getElementById('vaSub').textContent = p.sub;

    const names = Object.keys(players);
    const current = getCurrentDrinker();
    document.getElementById('vaNames').textContent =
      current ? `${current}, TAGAY MO NA!` : (names.length ? `Lahat kayo! — ${names.join(', ')}` : '');

    document.getElementById('voiceAlert').classList.add('show');
    playAlarmAudio();
  }

  document.addEventListener('keydown', e => {
    if (e.key === 'Enter' && document.getElementById('addPlayer').classList.contains('active')) addPlayer();
    if (e.key === 'Escape') { closeModal(false); dismissAlert(); }
  });

  function dismissAlert() {
    document.getElementById('voiceAlert').classList.remove('show');
    stopAlarmAudio();
    try {
      _unlockAudio();
      const dismissSound = new Audio(DISMISS_AUDIO_SRC);
      dismissSound.volume = 1;
      dismissSound.play().catch(() => setTimeout(() => dismissSound.play().catch(()=>{}), 400));
    } catch(e) {}
    if (Object.keys(players).length) {
      // Player didn't drink — skip their turn and move to next player
      const skipped = getCurrentDrinker();
      currentDrinkerIdx = (currentDrinkerIdx + 1) % drinkOrder.length;
      const next = getCurrentDrinker();
      clearInterval(timerIv);
      timerIv = null;
      timeLeft = timerSecs;
      timerRunning = true;
      timerIv = setInterval(tick, 1000);
      renderTimer();
      renderDrinkOrder();
      renderShotList();
      toast(`⏭ ${skipped} nilaktawan! Susunod: ${next} ⏱`);
    }
  }

  // ── Camera ─────────────────────────────────────────
  async function handleCamBtn() {
    if (camState === 'idle') {
      await startCamera();
    } else if (camState === 'live') {
      snapPhoto();
    }
  }

  async function startCamera() {
    try {
      // Stop any existing stream first
      stopCameraStream();

      // Check if mediaDevices is supported
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        document.getElementById('camStatus').textContent = '⚠️ Camera not supported on this browser';
        return;
      }

      // Request camera — try facing mode first, fall back to any camera
      let constraints = { video: { facingMode: camFacingMode }, audio: false };
      try {
        camStream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (e1) {
        // Fallback: try without facingMode (works on more devices)
        try {
          camStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
        } catch (e2) {
          document.getElementById('camStatus').textContent = '⚠️ Camera access denied — player added without photo';
          return;
        }
      }

      const video = document.getElementById('camVideo');
      video.srcObject = camStream;
      await video.play();
      video.style.display = 'block';
      document.getElementById('camPhoto').style.display = 'none';
      document.getElementById('camBtn').textContent = '📸 Take Photo';
      document.getElementById('camRetakeBtn').style.display = 'none';

      // Show switch button only if multiple cameras available
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        camDevices = devices.filter(d => d.kind === 'videoinput');
        document.getElementById('camSwitchBtn').style.display = camDevices.length > 1 ? 'block' : 'none';
      } catch(e) { /* ignore */ }

      document.getElementById('camStatus').textContent = '🎥 Camera live — smile!';
      camState = 'live';
    } catch (e) {
      document.getElementById('camStatus').textContent = '⚠️ Camera not available — player added without photo';
    }
  }

  async function switchCamera() {
    camFacingMode = camFacingMode === 'user' ? 'environment' : 'user';
    document.getElementById('camStatus').textContent = '🔄 Switching camera...';
    await startCamera();
  }

function snapPhoto() {
   const video  = document.getElementById('camVideo');
   const canvas = document.getElementById('camCanvas');
   const photo  = document.getElementById('camPhoto');

   canvas.width  = video.videoWidth || 320;
   canvas.height = video.videoHeight || 240;

   const ctx = canvas.getContext('2d');

  // Mirror front camera photo
  if (camFacingMode === 'user') {
    ctx.translate(canvas.width, 0);
    ctx.scale(-1, 1);
  }

   ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

   capturedPhoto = canvas.toDataURL('image/jpeg', 0.7);

   photo.src = capturedPhoto;
   photo.style.display = 'block';
   video.style.display = 'none';

   stopCameraStream();

   document.getElementById('camBtn').style.display = 'none';
   document.getElementById('camSwitchBtn').style.display = 'none';
   document.getElementById('camRetakeBtn').style.display = 'block';
   document.getElementById('camStatus').textContent = '✅ Photo captured!';

  camState = 'captured';
}

  // ── Navigation ─────────────────────────────────────
  function go(id) {
    document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
    document.getElementById(id).classList.add('active');
    if (id === 'takeShot')     { renderDrinkOrder(); renderShotList(); }
    if (id === 'removePlayer') renderRemoveList();
    if (id === 'leaderboard')  renderLeaderboard();
    if (id !== 'addPlayer')    resetCameraUI();
  }

  function cancelAddPlayer() {
    resetCameraUI();
    go('mainMenu');
  }

  function updateStats() {
    document.getElementById('roundNum').textContent    = round;
    document.getElementById('playerCount').textContent = Object.keys(players).length;
    document.getElementById('totalShots').textContent  = Object.values(players).reduce((a,p)=>a+p.shots,0);
  }

  let toastTm;
  function toast(msg) {
    const el = document.getElementById('toast');
    el.textContent = msg;
    el.classList.add('show');
    clearTimeout(toastTm);
    toastTm = setTimeout(() => el.classList.remove('show'), 2400);
  }

  function showModal(msg) {
    return new Promise(r => {
      modalResolve = r;
      document.getElementById('modalMsg').textContent = msg;
      document.getElementById('modalOverlay').classList.add('show');
      document.getElementById('modalConfirmBtn').onclick = () => closeModal(true);
    });
  }
  function closeModal(v) {
    document.getElementById('modalOverlay').classList.remove('show');
    if (modalResolve) { modalResolve(v); modalResolve = null; }
  }

  function addPlayer() {
    const inp  = document.getElementById('playerNameInput');
    const name = inp.value.trim();
    if (!name) { toast('⚠️ Enter a name!'); return; }
    if (players[name] !== undefined) { toast('⚠️ Already exists!'); return; }
    players[name] = { shots: 0, photo: capturedPhoto, stoppedAt: null, joinedRound: round };
    drinkOrder = Object.keys(players); // maintain sequential order
    currentDrinkerIdx = currentDrinkerIdx % drinkOrder.length;
    inp.value = '';
    resetCameraUI();
    updateStats();
    toast(`✅ ${name} added!`);
    go('mainMenu');
  }

  function badgeHTML() {
    if (!timerRunning) return `<span class="timer-badge badge-off">timer off</span>`;
    const m = Math.floor(timeLeft/60), s = timeLeft%60;
    const label = `${m}:${s.toString().padStart(2,'0')}`;
    if (timeLeft > 120) return `<span class="timer-badge badge-ok">⏱ ${label}</span>`;
    if (timeLeft > 30)  return `<span class="timer-badge badge-warn">⚠️ ${label}</span>`;
    return `<span class="timer-badge badge-danger">🔴 ${label}</span>`;
  }

  function reshuffleDrinkOrder() {
    // kept for compatibility, no-op now
  }

  function getCurrentDrinker() {
    if (!drinkOrder.length) return null;
    return drinkOrder[currentDrinkerIdx % drinkOrder.length];
  }

  function updateTimerBanner() {
    const current = getCurrentDrinker();
    const label = document.getElementById('timerLabel');
    const sub = document.getElementById('timerSub');
    if (current && drinkOrder.length > 1) {
      const nextIdx = (currentDrinkerIdx + 1) % drinkOrder.length;
      const next = drinkOrder[nextIdx];
      const turnNum = currentDrinkerIdx + 1;
      label.textContent = `🍺 ${current} — TAGAY MO NA!`;
      sub.textContent = `Susunod: ${next} · Turn ${turnNum} of ${drinkOrder.length}`;
    } else if (current) {
      label.textContent = `🍺 ${current} — TAGAY MO NA!`;
      sub.textContent = 'Hindi uminom → 🔊 ALARM tutunog!';
    } else {
      label.textContent = '🔔 Drink Timer — Iinomin o Dodoblehin';
      sub.textContent = 'Walang nag-iinom → 🔊 ALARM tutunog!';
    }
  }

  function renderDrinkOrder() {
    const wrap = document.getElementById('drinkOrderWrap');
    const list = document.getElementById('drinkOrderList');
    const names = Object.keys(players);
    if (!names.length) { wrap.style.display = 'none'; return; }

    // Build/sync drink order (sequential, no shuffle)
    if (!drinkOrder.length || drinkOrder.some(n => !players[n]) || names.some(n => !drinkOrder.includes(n))) {
      drinkOrder = [...names]; // sequential as added
      currentDrinkerIdx = 0;
    }

    wrap.style.display = 'block';
    const nextIdx = (currentDrinkerIdx + 1) % drinkOrder.length;
    list.innerHTML = drinkOrder.map((name, i) => {
      const p = players[name];
      const isCurrent = i === (currentDrinkerIdx % drinkOrder.length);
      const isNext    = drinkOrder.length > 1 && i === nextIdx && !isCurrent;
      const avatarHTML = p.photo
        ? `<img class="player-avatar" src="${p.photo}" alt="${name}" style="width:38px;height:38px;" />`
        : `<div class="avatar-placeholder" style="width:38px;height:38px;font-size:1rem;">🍺</div>`;
      const cardClass = isCurrent ? 'first-drinker' : isNext ? 'next-drinker' : '';
      const labelHTML = isCurrent
        ? `<span class="drink-label first">🍻 Tagay ngayon!</span>`
        : isNext
          ? `<span class="drink-label next-label">⏳ Susunod</span>`
          : '';
      return `
      <div class="drink-order-card ${cardClass}">
        <div class="drink-num ${isCurrent ? 'first' : isNext ? 'next-num' : ''}">${i + 1}</div>
        ${avatarHTML}
        <div style="flex:1">
          <div class="player-name" style="font-size:.95rem;">${name}</div>
          ${labelHTML}
        </div>
      </div>`;
    }).join('');

    updateTimerBanner();
  }

  function renderShotList() {
    const list = document.getElementById('shotList');
    const names = Object.keys(players);
    if (!names.length) {
      list.innerHTML = '<div class="empty-state"><div class="big">🍺</div>No players yet!<br>Add someone first.</div>';
      return;
    }
    const current = getCurrentDrinker();
    list.innerHTML = names.map(name => {
      const p = players[name];
      const shots = p.shots;
      const isCurrent = name === current;
      const avatarHTML = p.photo
        ? `<img class="player-avatar" src="${p.photo}" alt="${name}" />`
        : `<div class="avatar-placeholder">🍺</div>`;

      // Only the current drinker shows the live timer badge; others show "waiting"
      let badge;
      if (isCurrent) {
        badge = badgeHTML();
      } else {
        badge = `<span class="timer-badge badge-off">⏳ naghihintay</span>`;
      }

      // Only current player's Inom! button is active; others are dimmed
      const btnStyle = isCurrent ? '' : 'opacity:0.3;pointer-events:none;';

      return `
      <div class="player-card" style="${isCurrent ? 'border-color:rgba(245,158,11,.6);background:rgba(245,158,11,.08);' : ''}">
        ${avatarHTML}
        <div style="flex:1">
          <div class="player-name">${name}${isCurrent ? ' 🍻' : ''}</div>
          <div class="player-shots">${shots} shot${shots!==1?'s':''}</div>
          ${badge}
        </div>
        <button class="card-btn take" style="${btnStyle}" onclick="takeShot('${name}')">🍻 Inom!</button>
      </div>`;
    }).join('');
  }

  function takeShot(name) {
    players[name].shots++;
    updateStats();

    const nextIdx = (drinkOrder.indexOf(name) + 1) % drinkOrder.length;
    const nextPlayer = drinkOrder[nextIdx] || getCurrentDrinker();

    // Advance turn AND auto-restart timer for the next player
    advanceTurnAndRestart(name);
    renderDrinkOrder();
    renderShotList();
    updateTimerBanner();
    toast(`🍻 ${name} nainom! Susunod: ${nextPlayer} ⏱`);
  }

  function renderRemoveList() {
    const list = document.getElementById('removeList');
    const names = Object.keys(players);
    if (!names.length) {
      list.innerHTML = '<div class="empty-state"><div class="big">🤷</div>Walang players!</div>';
      return;
    }
    list.innerHTML = names.map(name => {
      const p = players[name];
      const avatarHTML = p.photo
        ? `<img class="player-avatar" src="${p.photo}" alt="${name}" />`
        : `<div class="avatar-placeholder">🍺</div>`;
      return `
      <div class="player-card">
        ${avatarHTML}
        <div style="flex:1">
          <div class="player-name">${name}</div>
          <div class="player-shots">${p.shots} shots</div>
        </div>
        <button class="card-btn remove" onclick="removePlayer('${name}')">❌ Remove</button>
      </div>`;
    }).join('');
  }

  async function removePlayer(name) {
    if (!await showModal(`Remove ${name}?`)) return;
    // Record the shot they stopped at before deleting
    if (players[name]) players[name].stoppedAt = players[name].shots;
    removedPlayers[name] = { ...players[name] };
    delete players[name];
    drinkOrder = Object.keys(players);
    currentDrinkerIdx = drinkOrder.length ? currentDrinkerIdx % drinkOrder.length : 0;
    updateStats();
    renderRemoveList();
    toast(`🚪 ${name} nawala na! Mahinang Nilalang 🎵`);
    playRemoveAudio();
  }

  function renderLeaderboard() {
    const list   = document.getElementById('lbList');
    const sorted = Object.entries(players).sort(([,a],[,b])=>b.shots-a.shots);
    if (!sorted.length) {
      list.innerHTML = '<div class="empty-state"><div class="big">🏆</div>Walang data pa!</div>';
      return;
    }
    const max = Math.max(...sorted.map(([,p])=>p.shots), 1);
    const rc  = ['gold','silver','bronze'];
    list.innerHTML = sorted.map(([name,p],i) => {
      const avatarHTML = p.photo
        ? `<img class="player-avatar" src="${p.photo}" alt="${name}" style="width:44px;height:44px;" />`
        : `<div class="lb-rank ${rc[i]||''}">${i+1}.</div>`;
      return `
      <div class="lb-card">
        <div class="lb-top">
          ${p.photo ? `<div style="display:flex;align-items:center;gap:10px;">${avatarHTML}<div class="lb-rank ${rc[i]||''}" style="font-size:1.3rem">${i+1}.</div></div>` : avatarHTML}
          <div class="lb-name">${name}</div>
          <div class="lb-shots">${p.shots} 🍺</div>
        </div>
        <div class="bar-track">
          <div class="bar-fill" style="width:${Math.round((p.shots/max)*100)}%"></div>
        </div>
      </div>`;
    }).join('');
  }

  function doNextRound() {
    round++;
    resetCountdown();
    updateStats();
    toast(`🎉 Round ${round} — Mag-inom na!`);
  }

  async function confirmReset() {
    if (!await showModal('Reset everything? All data cleared.')) return;
    players = {}; removedPlayers = {}; round = 1; drinkOrder = []; currentDrinkerIdx = 0;
    stopTimer();
    updateStats();
    go('mainMenu');
    toast('🔄 Game reset!');
  }

  // ── Receipt ────────────────────────────────────────
  function buildReceiptData() {
    const active  = Object.entries(players).map(([name, p]) => ({ name, shots: p.shots, stopped: false }));
    const removed = Object.entries(removedPlayers).map(([name, p]) => ({ name, shots: p.shots, stopped: true, stoppedAt: p.stoppedAt }));
    const all = [...active, ...removed].sort((a,b) => b.shots - a.shots);
    return all;
  }

  function rankChip(i, stopped) {
    if (stopped) return `<span class="r-rank-chip r-stopped">🚫 Stopped</span>`;
    if (i === 0) return `<span class="r-rank-chip r-gold">🥇 Champion</span>`;
    if (i === 1) return `<span class="r-rank-chip r-silver">🥈 2nd Place</span>`;
    if (i === 2) return `<span class="r-rank-chip r-bronze">🥉 3rd Place</span>`;
    return `<span class="r-rank-chip r-normal">✅ Active</span>`;
  }

  function generateBarcode() {
    const bars = document.getElementById('receiptBarcode');
    bars.innerHTML = '';
    const widths = [2,1,3,1,2,1,1,3,2,1,3,2,1,1,2,3,1,2,1,3,2,1,2,1,3,1,2,3,1,2];
    widths.forEach((w,i) => {
      const s = document.createElement('span');
      s.style.width  = (w) + 'px';
      s.style.height = (i % 3 === 0 ? 36 : i % 2 === 0 ? 28 : 22) + 'px';
      s.style.opacity = i % 4 === 3 ? '0' : '1';
      bars.appendChild(s);
    });
  }

  function showReceipt() {
    const data = buildReceiptData();
    const now  = new Date();
    const dateStr = now.toLocaleDateString('en-PH', { weekday:'short', year:'numeric', month:'short', day:'numeric' });
    const timeStr = now.toLocaleTimeString('en-PH', { hour:'2-digit', minute:'2-digit' });
    const totalShots = data.reduce((a,p) => a + p.shots, 0);
    const txnId = 'TGY-' + Math.random().toString(36).slice(2,8).toUpperCase();

    let rowsHTML = '';
    let activeCount = 0, stoppedCount = 0;
    data.forEach((p, i) => {
      if (p.stopped) stoppedCount++; else activeCount++;
      const activeRank = p.stopped ? -1 : data.filter(x=>!x.stopped).indexOf(p);
      rowsHTML += `
        <div class="r-row">
          <div class="r-row-left">
            <div class="r-player-name">${p.name}</div>
            <div class="r-player-detail">
              ${p.stopped
                ? `Stopped drinking at shot #${p.stoppedAt ?? p.shots}`
                : `Currently playing · Shot #${p.shots}`}
            </div>
            ${rankChip(activeRank, p.stopped)}
          </div>
          <div class="r-shots-badge">${p.shots} 🍺</div>
        </div>`;
    });

    document.getElementById('receiptBody').innerHTML = `
      <div class="r-meta">
        <span>${dateStr}</span>
        <span>${timeStr}</span>
      </div>
      <div class="r-meta" style="margin-top:-6px;">
        <span>TXN: ${txnId}</span>
        <span>Round ${round}</span>
      </div>

      <div class="r-section-label">🏆 Player Summary</div>
      ${data.length ? rowsHTML : '<div style="color:#999;font-size:.82rem;text-align:center;padding:12px 0;">No players yet!</div>'}

      <div class="r-totals">
        <div class="r-total-row"><span>Active Players</span><span>${activeCount}</span></div>
        <div class="r-total-row"><span>Stopped / Removed</span><span>${stoppedCount}</span></div>
        <div class="r-total-row"><span>Current Round</span><span>${round}</span></div>
        <div class="r-total-row big"><span>TOTAL SHOTS 🍺</span><span>${totalShots}</span></div>
      </div>`;

    generateBarcode();
    document.getElementById('receiptOverlay').classList.add('show');
  }

  function closeReceipt() {
    document.getElementById('receiptOverlay').classList.remove('show');
  }

  function downloadReceipt() {
    const data     = buildReceiptData();
    const now      = new Date();
    const dateStr  = now.toLocaleDateString('en-PH', { weekday:'short', year:'numeric', month:'short', day:'numeric' });
    const timeStr  = now.toLocaleTimeString('en-PH', { hour:'2-digit', minute:'2-digit' });
    const totalShots = data.reduce((a,p) => a + p.shots, 0);
    const txnId = 'TGY-' + Math.random().toString(36).slice(2,8).toUpperCase();

    // Build plain-text receipt
    const line = (label, value, width=32) => {
      const dots = '.'.repeat(Math.max(1, width - label.length - String(value).length));
      return `${label}${dots}${value}`;
    };
    const divider = '================================';
    const dashes  = '--------------------------------';
    let txt = [
      divider,
      '       🍺  T A G A Y A N  🍺',
      '     Official Drinking Receipt',
      divider,
      `Date: ${dateStr}`,
      `Time: ${timeStr}`,
      `TXN:  ${txnId}`,
      `Round: ${round}`,
      dashes,
      '         PLAYER SUMMARY',
      dashes,
    ];

    data.forEach((p, i) => {
      const rank = p.stopped ? 'STOPPED' : (i === 0 ? '1ST PLACE' : i === 1 ? '2ND PLACE' : i === 2 ? '3RD PLACE' : 'ACTIVE');
      txt.push(line(p.name, `${p.shots} shots`));
      txt.push(`  [${rank}]${p.stopped ? ` Stopped at shot #${p.stoppedAt ?? p.shots}` : ''}`);
    });

    txt = txt.concat([
      dashes,
      line('Active Players', data.filter(p=>!p.stopped).length),
      line('Stopped/Removed', data.filter(p=>p.stopped).length),
      line('Current Round', round),
      divider,
      line('TOTAL SHOTS 🍺', totalShots),
      divider,
      '',
      '  * SALAMAT SA TAGAY! *',
      '  Drink responsibly. Stay safe.',
      divider,
    ]);

    const blob = new Blob([txt.join('\n')], { type: 'text/plain' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = `tagayan-receipt-${txnId}.txt`;
    a.click();
    URL.revokeObjectURL(url);
    toast('📄 Receipt downloaded!');
  }

  document.getElementById('receiptOverlay').addEventListener('click', function(e) {
    if (e.target === this) closeReceipt();
  });

  updateStats();
  renderTimer();